package vn.edu.fpt.seal.modules.audit.mapper; import vn.edu.fpt.seal.modules.audit.dto.AuditLogResponse; import vn.edu.fpt.seal.modules.audit.entity.AuditLog;
public final class AuditLogMapper{private AuditLogMapper(){} public static AuditLogResponse toResponse(AuditLog a){return AuditLogResponse.builder().id(a.getId()).userId(a.getUser()==null?null:a.getUser().getId()).userEmail(a.getUser()==null?null:a.getUser().getEmail()).teamId(a.getTeam()==null?null:a.getTeam().getId()).teamName(a.getTeam()==null?null:a.getTeam().getName()).incidentId(a.getIncident()==null?null:a.getIncident().getId()).action(a.getAction()).targetType(a.getTargetType()).targetId(a.getTargetId()).oldValue(a.getOldValue()).newValue(a.getNewValue()).details(a.getDetails()).occurredAt(a.getOccurredAt()).build();}}
